	if _, ok := jwk.Key.([]byte); ok {
		public = *jwk
	} else {
		public = jwk.Public()
	}

	b, err = json.MarshalIndent(public, "", "  ")
	if err != nil {
		return errors.Wrap(err, "error marshaling JWK")
	}

	fmt.Println(string(b))
